beforeExample:
class Example {
    /**
     * Some description
     */
    private boolean immutable = false;

    public void setImmutable() {
        immutable = true;
    }

    public boolean isImmutable() {
        return immutable;
    }
}

afterExample:
class Example {
    /**
     * Some description
     */
    private volatile boolean immutable;

    public void setImmutable() {
        immutable = true;
    }

    public boolean isImmutable() {
        return immutable;
    }
}

negativeExample:
class Example {
    // Should not match: already volatile
    private volatile boolean immutable = false;

    // Should not match: not boolean
    private int counter = 0;

    // Should not match: not initialized to false
    private boolean enabled;

    // Should not match: not private
    protected boolean accessible = false;
}
